      "core": "İslam’a göre insan Allah tarafından yaratılmış; akıl, irade ve sorumlulukla donatılmıştır. Kendini ve çevresini tanıma çabası, insanın yaratılışını ve hayatının anlamını düşünmesine yardımcı olur."
